/**
 * Web crypto facade over the Rust core compiled to WASM (src/lib/wasm, generated by
 * scripts/generate-bindings.sh — do not edit generated files).
 * The master key never enters JS: deriveAuthMaterial returns only the HKDF-separated
 * AuthVerifier (sent to server) and KEK (wraps the vault key locally).
 * NOTE: Argon2id (64 MiB) runs on the calling thread; move to a Web Worker in Phase 2 hardening.
 */
import init, {
  deriveAuthMaterial, generateKdfParams, randomKeyB64, wrapKeyB64, unwrapKeyB64,
  encryptItem, decryptItem, generateRecoveryKey, parseRecoveryKey, totpAt, generatePassword,
  generateTotpSecretB32,
} from "./wasm/openpass_core.js";

let ready: Promise<void> | null = null;
export function ensureCrypto(): Promise<void> {
  if (!ready) ready = init().then(() => undefined);
  return ready;
}

export interface KdfParams { memoryKib: number; iterations: number; parallelism: number; saltB64: string }
export interface AuthMaterial { authVerifierB64: string; kekB64: string }

export async function newKdfParams(): Promise<KdfParams> {
  await ensureCrypto();
  return JSON.parse(generateKdfParams()) as KdfParams;
}
export async function derive(password: string, params: KdfParams): Promise<AuthMaterial> {
  await ensureCrypto();
  return JSON.parse(deriveAuthMaterial(password, JSON.stringify(params))) as AuthMaterial;
}
export async function randomKey(): Promise<string> { await ensureCrypto(); return randomKeyB64(); }
export async function wrapKey(wrapperB64: string, keyB64: string): Promise<string> { await ensureCrypto(); return wrapKeyB64(wrapperB64, keyB64); }
export async function unwrapKey(wrapperB64: string, blobB64: string): Promise<string> { await ensureCrypto(); return unwrapKeyB64(wrapperB64, blobB64); }

export interface EncryptedItemPayload { ciphertextB64: string; wrappedItemKeyB64: string }
export async function encryptItemJson(vaultKeyB64: string, itemId: string, plaintext: unknown): Promise<EncryptedItemPayload> {
  await ensureCrypto();
  return JSON.parse(encryptItem(vaultKeyB64, itemId, JSON.stringify(plaintext))) as EncryptedItemPayload;
}
export async function decryptItemJson<T>(vaultKeyB64: string, itemId: string, item: EncryptedItemPayload): Promise<T> {
  await ensureCrypto();
  return JSON.parse(decryptItem(vaultKeyB64, itemId, item.ciphertextB64, item.wrappedItemKeyB64)) as T;
}
export async function newRecoveryKey(): Promise<{ text: string; keyB64: string }> {
  await ensureCrypto();
  return JSON.parse(generateRecoveryKey()) as { text: string; keyB64: string };
}
export async function parseRecovery(text: string): Promise<string> { await ensureCrypto(); return parseRecoveryKey(text); }
export async function totp(secretB32: string, atSeconds = Math.floor(Date.now() / 1000), digits = 6, sha256 = false): Promise<string> {
  await ensureCrypto();
  return totpAt(secretB32, BigInt(atSeconds), 30n, digits, sha256);
}
export async function makePassword(length = 20): Promise<string> { await ensureCrypto(); return generatePassword(length); }
export async function newTotpSecret(): Promise<string> { await ensureCrypto(); return generateTotpSecretB32(); }
